  <div class="od-totals"><div><span>Tax <?= !empty($financial['tax_inclusive'])?'(included)':'' ?></span><span>₱<?= number_format(($financial['tax_cents']??0)/100,2) ?></span></div><div><span>Service charge</span><span>₱<?= number_format(($financial['service_cents']??0)/100,2) ?></span></div><?php if($isDelivery): ?><div><span>Delivery</span><span>₱<?= number_format((float)($selected['delivery_fee']??0),2) ?></span></div><?php endif; ?><div class="od-total"><span>Order total</span><strong>₱<?= number_format((float)$selected['total'],2) ?></strong></div><div class="od-payment-state"><span>Payment status</span><span class="payment-tag payment-<?= $h($selected['payment_status']) ?>"><?= $h(ucfirst($selected['payment_status'])) ?></span></div></div></section>
